'use strict';
const $ = id => document.getElementById(id);
const demoStops = [
 {id:'chenliu',name:'陈留',era:'魏晋 · 姓氏文化',subtitle:'今河南开封附近 · 示意位置',coordinates:[114.52,34.69],text:'你提供的材料以阮籍、阮咸与“竹林堂”联系作为姓氏文化背景。这一站用于展示文化溯源，不能据此认定两人是查询者的直系祖先，也不能补出他们与后世支系之间的世系。',source:'来源：本次对话中用户提供的材料。尚未取得原始文献或谱页；历史人物关系与堂号来源需分别核查。此站不与后面的迁徙路线连线。'},
 {id:'leping',name:'乐平',era:'迁出线索 · 年代待核查',subtitle:'今江西乐平附近 · 原村址未确认',coordinates:[117.13,28.97],text:'演示材料称，阮四一于1275年前后自江西饶州乐平杏花村迁出。这是候选迁徙线索，尚未核对原谱。材料还提及江西吉安，两个地名之间的关系需要进一步查证，暂不拼成连续世系。',source:'来源：用户提供的“阮四一，南宋德祐元年（1275）迁兴国州”文字。没有提供宗亲网原始链接、谱名或页码；年份、村址和迁徙原因均待核查。'},
 {id:'yangxin',name:'阳新',era:'迁入线索 · 1275年说法',subtitle:'今湖北阳新附近 · 古今范围待核对',coordinates:[115.22,29.83],text:'材料把兴国州与今天的阳新、通山地区联系起来。此处以现代阳新附近作为地图示意，不代表已经确定的落脚村庄。若选择“英士中州启”，界面保留阳新支候选，但字辈本身无法确认亲属关系。',source:'来源：用户提供的迁徙与阳新字辈材料。古兴国州行政范围、始迁记载及支系分化，需要地方志和谱牒原文互证。'},
 {id:'tongshan',name:'通山',era:'家乡线索 · 分支年代未明',subtitle:'湖北通山 · 黄沙铺大源候选',coordinates:[114.49,29.6],text:'“英、士、班、家、国”是这次原型中的关键线索。根据你提供的材料，它指向通山黄沙大源候选支系。它能帮助缩小查询范围，但尚不能证明查询者属于该支，也无法推出父亲、祖父或完整祖先名单。',source:'来源：本次对话中用户提供的字辈与支系说法。尚未取得原谱；“士 / 仕”是否为同一辈、分房关系及完整字辈，需要单独核对。'}
];
let stops=demoStops.slice(),map,ready=false,active=null,branch=null,query=null,currentRoutes=[];
const markers=[];const provinceMarkers=[];
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function safeUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function linkSource(container,source){const url=safeUrl(source.url);if(!url)return;const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title||new URL(url).hostname;container.append(a);}
function showView(view){$('workspace').dataset.view=view;$('tab-chat').setAttribute('aria-selected',String(view==='chat'));$('tab-map').setAttribute('aria-selected',String(view==='map'));if(view==='map')requestAnimationFrame(()=>map?.resize());}
function mapPadding(){const shell=document.querySelector('.map-shell').getBoundingClientRect();const mobile=window.innerWidth<=760;const detail=$('history').hidden?0:$('history').getBoundingClientRect().height;return {top:mobile?150:170,bottom:mobile?Math.min(detail+180,shell.height-210):165,left:mobile?24:40,right:mobile?24:($('history').hidden?40:350)};}
function selectStop(id,fly=true,openView=true){const stop=stops.find(s=>s.id===id);if(!stop)throw new Error('未知地点');active=id;$('history').hidden=false;$('era').textContent=stop.era||'本次查询线索';$('location-title').textContent=stop.name;$('location-subtitle').textContent=stop.subtitle||'位置为区域示意';$('history-copy').textContent=stop.text||'';$('location-evidence').textContent=stop.evidence||'待核查';$('source-copy').replaceChildren();if(stop.sources?.length){for(const source of stop.sources)linkSource($('source-copy'),source);}else{const p=document.createElement('p');p.textContent=stop.source||'尚缺可核对的来源。';$('source-copy').append(p);}document.querySelectorAll('.stop').forEach(el=>{const isActive=el.dataset.id===id;el.classList.toggle('active',isActive);el.setAttribute('aria-current',isActive?'location':'false');});markers.forEach(m=>m.el.classList.toggle('active',m.id===id));if(fly&&(openView||window.innerWidth>760||$('workspace').dataset.view==='map')){if(openView)showView('map');requestAnimationFrame(()=>{if(ready)map.flyTo({center:stop.coordinates,zoom:stop.precision==='province'?6:8.6,pitch:48,bearing:-10,duration:reduced?0:1600,padding:mapPadding()});});}$('map-toast').textContent='已定位 '+stop.name;$('map-toast').hidden=false;return {selected:id,name:stop.name};}
function overview(){if(!ready)return;$('history').hidden=true;$('map-toast').hidden=true;map.resize();if(!stops.length){map.flyTo({center:[105,34],zoom:3.6,pitch:20,bearing:0,padding:{top:120,bottom:140,left:30,right:30},duration:reduced?0:1400});return;}const bounds=new maplibregl.LngLatBounds();for(const stop of stops)bounds.extend(stop.coordinates);map.fitBounds(bounds,{padding:mapPadding(),pitch:25,bearing:0,maxZoom:6.5,duration:reduced?0:1400});}
function renderStops(){ $('stops').replaceChildren();$('place-count').textContent=stops.length+' 处线索';$('mobile-count').textContent=String(stops.length);$('map-empty').hidden=stops.length>0;for(const stop of stops){const b=document.createElement('button');b.type='button';b.className='stop';b.dataset.id=stop.id;b.append(document.createTextNode(stop.name));const small=document.createElement('small');small.textContent=stop.evidence|| (stop.id==='chenliu'?'文化背景':'待核查');b.append(small);b.addEventListener('click',()=>selectStop(stop.id));$('stops').append(b);} }
function syncMap(){if(!ready)return;for(const marker of markers)marker.marker.remove();markers.length=0;for(const stop of stops){const el=document.createElement('button');el.type='button';el.className='pin';el.textContent=stop.name;el.setAttribute('aria-label','查看 '+stop.name);el.addEventListener('click',()=>selectStop(stop.id));const marker=new maplibregl.Marker({element:el,anchor:'bottom'}).setLngLat(stop.coordinates).addTo(map);markers.push({id:stop.id,el,marker});}const features=currentRoutes.map(route=>{const from=stops.find(s=>s.id===route.fromId),to=stops.find(s=>s.id===route.toId);return from&&to?{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:[from.coordinates,to.coordinates]}}:null;}).filter(Boolean);map.getSource('route').setData({type:'FeatureCollection',features});map.setLayoutProperty('route-line','visibility',window.routeRevealed?'visible':'none');}
function setMapDataset(nodes,routes=[]){stops=nodes.filter(s=>Array.isArray(s.coordinates)&&s.coordinates.length===2&&s.coordinates.every(Number.isFinite));currentRoutes=routes;active=null;$('history').hidden=true;$('map-toast').hidden=true;renderStops();syncMap();}
function useDemoMap(){window.routeRevealed=false;setMapDataset(demoStops.slice(),[{fromId:'leping',toId:'yangxin'},{fromId:'yangxin',toId:'tongshan'}]);$('map-heading').textContent='从家乡出发';$('route-caption').textContent='阮氏背景示例 · 不代表你的祖先';$('timeline-title').textContent='先探索这些背景地点';overview();}
function useLiveMap(){window.routeRevealed=false;setMapDataset([]);$('map-heading').textContent='等待你的第一条线索';$('route-caption').textContent='仅展示本次查询有来源的地点';$('timeline-title').textContent='本次查询地点';overview();}
function revealRoute(){window.routeRevealed=true;$('route-caption').textContent='候选迁徙示意 · 待核查，非实际行走路线';$('map-heading').textContent='沿着线索，看见来路';syncMap();showView('map');requestAnimationFrame(overview);}
function updateResearchMap(result){const sources=new Map((result.sources||[]).map(s=>[s.id,s]));const raw=result.mapNodes||[];const nodes=[];for(const node of raw){if(!node.sourceIds?.some(id=>sources.has(id)))continue;const lng=node.lng,lat=node.lat;if(!Number.isFinite(lng)||!Number.isFinite(lat)||Math.abs(lng)>180||Math.abs(lat)>90)continue;nodes.push({id:node.id,name:node.name,coordinates:[lng,lat],precision:node.precision,era:node.year?String(node.year):'公开资料线索',subtitle:node.precision==='exact'?'文献提供的位置':'区域示意 · 非祖居精确位置',text:node.summary,evidence:'有来源线索',sources:node.sourceIds.map(id=>sources.get(id)).filter(Boolean)});}
for(const clue of result.clues||[]){const location=clue.location;if(!location?.name||!clue.sourceIds?.some(id=>sources.has(id)))continue;if(nodes.some(n=>n.id===clue.id))continue;const province=window.provinceData.features.find(f=>location.name.includes(f.properties.name)||location.name.includes(f.properties.name.replace(/省|市|壮族自治区|回族自治区|维吾尔自治区|自治区/g,'')));if(!province)continue;const name=province.properties.name;if(nodes.some(n=>n.name===name))continue;nodes.push({id:clue.id,name,coordinates:province.properties.centroid||province.properties.center,precision:'province',era:'相关资料 · 省域示意',subtitle:'资料涉及 '+location.name+'，地图仅标省域',text:clue.summary,evidence:'区域示意',sources:clue.sourceIds.map(id=>sources.get(id)).filter(Boolean)});}
const routes=(result.routes||[]).filter(r=>r.sourceIds?.some(id=>sources.has(id))&&nodes.some(n=>n.id===r.fromId&&n.precision!=='province')&&nodes.some(n=>n.id===r.toId&&n.precision!=='province'));window.routeRevealed=routes.length>0;setMapDataset(nodes,routes);$('map-heading').textContent=nodes.length?'本次探索的来路':'已有线索，位置尚待确认';$('route-caption').textContent=routes.length?'有来源支持的候选迁徙联系':'地点线索不自动组成迁徙路线';$('timeline-title').textContent='本次查询地点';overview();return nodes.length;}
$('tab-chat').addEventListener('click',()=>showView('chat'));$('tab-map').addEventListener('click',()=>{showView('map');requestAnimationFrame(overview);});$('overview').addEventListener('click',overview);$('close-history').addEventListener('click',()=>{$('history').hidden=true;});$('ask-location').addEventListener('click',()=>{const stop=stops.find(s=>s.id===active);if(!stop)return;showView('chat');$('question').value='关于'+stop.name+'，还有哪些家族历史线索和可查证的来源？';$('question').focus();});
renderStops();
try{if(!window.maplibregl)throw new Error('地图组件未加载');map=new maplibregl.Map({container:'map',style:{version:8,sources:{provinces:{type:'geojson',data:window.provinceData,attribution:'省级示意边界：DataV GeoAtlas'}},layers:[{id:'background',type:'background',paint:{'background-color':'#162d3b'}},{id:'province-fill',type:'fill',source:'provinces',paint:{'fill-color':'#173b4a','fill-opacity':0.62}},{id:'province-border',type:'line',source:'provinces',paint:{'line-color':'#7396a1','line-width':1,'line-opacity':0.6}}]},center:[115.4,31.1],zoom:5.6,pitch:25,bearing:0,attributionControl:true});map.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');const timeout=setTimeout(()=>{if(!ready){$('map-status').textContent='地图暂未打开，仍可继续对话查看线索。';}},15000);map.on('load',()=>{ready=true;clearTimeout(timeout);$('map-status').hidden=true;map.addSource('basemap',{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'});map.addLayer({id:'basemap',type:'raster',source:'basemap',paint:{'raster-opacity':0.8}},'province-fill');map.addSource('elevation',{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],tileSize:256,encoding:'terrarium',maxzoom:13,attribution:'Elevation: AWS Terrain Tiles'});map.addControl(new maplibregl.TerrainControl({source:'elevation',exaggeration:1.3}));for(const feature of window.provinceData.features){const p=feature.properties;if(!p.center||!['湖北省','江西省','河南省','湖南省','安徽省','浙江省','福建省','江苏省','山东省','陕西省','四川省','重庆市'].includes(p.name))continue;const el=document.createElement('span');el.className='province-label';el.textContent=p.name;new maplibregl.Marker({element:el}).setLngLat(p.center).addTo(map);provinceMarkers.push(el);}map.addSource('route',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'route-line',type:'line',source:'route',layout:{visibility:'none'},paint:{'line-color':'#edc18a','line-width':2.5,'line-dasharray':[2,3],'line-opacity':0.95}});syncMap();overview();});map.on('zoom',()=>provinceMarkers.forEach(el=>el.hidden=map.getZoom()>7));map.on('error',e=>console.warn('Map source unavailable',e.error?.message));}catch(e){$('map-status').textContent='地图暂未打开，仍可继续对话查看线索。';}
